+              </div>
+            </form>
+          </section>
+        `;
+      }
+
+      function SupportHero() {
+        return `
+          <section class="hero" aria-labelledby="page-title">
+            <div>
+              <span class="eyebrow">Support team</span>
+              <h1 id="page-title">Talk to product support without the back-and-forth.</h1>
+              <p>
+                Share your details and our team will follow up with the right troubleshooting guidance,
+                account help, or product answers.
+              </p>
+            </div>
+            <ul class="feature-list" aria-label="Support highlights">
+              <li>
+                <span class="bullet" aria-hidden="true"></span>
+                <div>
+                  <strong>Fast routing</strong>
+                  Requests are triaged so customers reach the right specialist sooner.
+                </div>
+              </li>
+              <li>
+                <span class="bullet" aria-hidden="true"></span>
+                <div>
+                  <strong>Clear follow-up</strong>
+                  Contact details are collected in a simple format with immediate validation feedback.
+                </div>
+              </li>
+              <li>
+                <span class="bullet" aria-hidden="true"></span>
+                <div>
+                  <strong>Built for every screen</strong>
+                  The layout stays readable from small mobile widths to larger desktop views.
+                </div>
+              </li>
+            </ul>
+          </section>
+        `;
+      }
+
+      function App() {
+        return `
+          <main id="maincontent" tabindex="-1">
+            <div class="page-shell">
+              ${SupportHero()}
+              ${ContactForm()}
+            </div>
+          </main>
+        `;
+      }
+
+      function escapeHtml(value) {
+        return value
+          .replaceAll("&", "&amp;")
+          .replaceAll('"', "&quot;")
+          .replaceAll("<", "&lt;")
+          .replaceAll(">", "&gt;");
+      }
+
+      function render() {
+        document.getElementById("app").innerHTML = App();
+        const form = document.getElementById("support-form");
+        const fields = fieldConfig().map((field) => document.getElementById(field.id));
+
+        fields.forEach((input) => {
+          input.addEventListener("input", handleInput);
+          input.addEventListener("blur", handleBlur);
+        });
+
+        form.addEventListener("submit", handleSubmit);
+      }
+
+      function updateState(nextState, shouldFocusId) {
+        state = {
+          ...state,
+          ...nextState,
+          values: {
+            ...state.values,
+            ...(nextState.values || {})
+          }
+        };
+
+        render();
+
+        if (shouldFocusId) {
+          const target = document.getElementById(shouldFocusId);
+          if (target) {
+            target.focus();
+          }
+        }
+      }
+
+      function handleInput(event) {
+        const { name, value } = event.target;
+        const nextValues = { ...state.values, [name]: value };
+        const nextErrors = { ...state.errors };
+
+        if (nextErrors[name]) {
+          const refreshedErrors = validate(nextValues);
+          if (!refreshedErrors[name]) {
+            delete nextErrors[name];
+          } else {
+            nextErrors[name] = refreshedErrors[name];
+          }
+        }
+
+        updateState({
+          values: nextValues,
+          errors: nextErrors,
+          submitMessage: ""
+        });
+      }
+
+      function handleBlur(event) {
+        const { name, value } = event.target;
+        const nextValues = { ...state.values, [name]: value };
+        const refreshedErrors = validate(nextValues);
+        const nextErrors = { ...state.errors };
+
+        if (refreshedErrors[name]) {
+          nextErrors[name] = refreshedErrors[name];
+        } else {
+          delete nextErrors[name];
+        }
+
+        updateState({
+          values: nextValues,
+          errors: nextErrors,
+          submitMessage: ""
+        });
+      }
+
+      function handleSubmit(event) {
+        event.preventDefault();
+        const nextErrors = validate(state.values);
+        const firstInvalidId = fieldConfig().find((field) => nextErrors[field.id])?.id;
+
+        if (firstInvalidId) {
+          updateState(
+            {
+              errors: nextErrors,
+              submitMessage: ""
+            },
+            firstInvalidId
+          );
+          return;
+        }
+
+        updateState({
+          errors: {},
+          submitMessage: "Thanks. Your support request is ready to be reviewed."
+        });
+      }
+
+      render();
+    </script>
+  </body>
+</html>
