+        if (firstInvalidId) {
+          updateState(
+            {
+              errors: nextErrors,
+              submitMessage: ""
+            },
+            firstInvalidId
+          );
+          return;
+        }
+
+        updateState({
+          errors: {},
+          submitMessage: "Thanks. Your support request is ready to be reviewed."
+        });
+      }
+
+      render();
+    </script>
+  </body>
