288.       let state = { ...initialState, values: { ...initialState.values } };
289. 
290.       const phonePattern = /^(?:\+?\d{1,2}\s?)?(?:\(\d{3}\)|\d{3})[\s-]?\d{3}[\s-]?\d{4}$/;
