292.       function validate(values) {
293.         const errors = {};
294.         const trimmedName = values.fullName.trim();
295.         const trimmedEmail = values.email.trim();
296.         const trimmedPhone = values.phone.trim();
297. 
298.         if (!trimmedName) {
299.           errors.fullName = "Error: Enter your full name.";
300.         }
301. 
302.         if (!trimmedEmail) {
303.           errors.email = "Error: Enter your email address.";
304.         } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedEmail)) {
305.           errors.email = "Error: Enter a valid email address, like name@example.com.";
306.         }
307. 
308.         if (trimmedPhone && !phonePattern.test(trimmedPhone)) {
309.           errors.phone = "Error: Enter a phone number like (555) 123-4567.";
310.         }
311. 
312.         return errors;
313.       }
