290.       let state = { ...initialState, values: { ...initialState.values } };
291. 
292.       const phonePattern = /^(?:\+?\d{1,2}\s?)?(?:\(\d{3}\)|\d{3})[\s-]?\d{3}[\s-]?\d{4}$/;
293. 
294.       function validate(values) {
295.         const errors = {};
296.         const trimmedName = values.fullName.trim();
297.         const trimmedEmail = values.email.trim();
298.         const trimmedPhone = values.phone.trim();
299. 
300.         if (!trimmedName) {
301.           errors.fullName = "Error: Enter your full name.";
302.         }
303. 
304.         if (!trimmedEmail) {
305.           errors.email = "Error: Enter your email address.";
306.         } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedEmail)) {
307.           errors.email = "Error: Enter a valid email address, like name@example.com.";
308.         }
309. 
310.         if (trimmedPhone && !phonePattern.test(trimmedPhone)) {
311.           errors.phone = "Error: Enter a phone number like (555) 123-4567.";
312.         }
313. 
314.         return errors;
315.       }
316. 
317.       function fieldConfig() {
318.         return [
319.           {
320.             id: "fullName",
321.             label: "Full name",
322.             type: "text",
323.             required: true,
324.             autocomplete: "name",
325.             placeholder: "Taylor Morgan"
326.           },
327.           {
328.             id: "email",
329.             label: "Email address",
330.             type: "email",
331.             required: true,
332.             autocomplete: "email",
333.             placeholder: "taylor@example.com"
334.           },
335.           {
336.             id: "phone",
337.             label: "Phone number",
338.             type: "tel",
339.             required: false,
340.             autocomplete: "tel",
341.             placeholder: "(555) 123-4567",
342.             helperText: "Optional. Use a format like (555) 123-4567."
343.           }
344.         ];
345.       }
346. 
347.       function FormField({ id, label, type, required, autocomplete, placeholder, helperText }) {
348.         const error = state.errors[id];
349.         const describedBy = [helperText ? id + "-help" : "", error ? id + "-error" : ""]
350.           .filter(Boolean)
351.           .join(" ");
352. 
353.         return `
354.           <div class="form-field">
355.             <label for="${id}">
356.               ${label}${required ? '<span class="required-indicator" aria-hidden="true">*</span>' : ' <span aria-hidden="true">(optional)</span>'}
357.             </label>
358.             <input
359.               id="${id}"
360.               name="${id}"
361.               type="${type}"
362.               ${required ? "required" : ""}
363.               autocomplete="${autocomplete}"
364.               placeholder="${placeholder}"
365.               value="${escapeHtml(state.values[id])}"
366.               ${describedBy ? 'aria-describedby="' + describedBy + '"' : ""}
367.               ${error ? 'aria-invalid="true" aria-errormessage="' + id + '-error"' : 'aria-invalid="false"'}
368.             />
369.             ${helperText ? '<p class="helper-text" id="' + id + '-help">' + helperText + "</p>" : ""}
370.             <p class="error-message" id="${id}-error"${error ? "" : ' hidden'}>${error || ""}</p>
371.           </div>
372.         `;
373.       }
374. 
375.       function ContactForm() {
376.         return `
377.           <section class="card" aria-labelledby="contact-form-title">
378.             <h2 id="contact-form-title">Send a support request</h2>
379.             <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required fields</p>
380.             <form id="support-form" novalidate>
381.               ${fieldConfig().map(FormField).join("")}
382.               <div class="button-row">
