384.                 <button type="submit">Send request</button>
385.               </div>
386.             </form>
387.           </section>
388.         `;
389.       }
390. 
391.       function SupportHero() {
392.         return `
393.           <section class="hero" aria-labelledby="page-title">
394.             <div>
395.               <span class="eyebrow">Support team</span>
396.               <h1 id="page-title">Talk to product support without the back-and-forth.</h1>
397.               <p>
398.                 Share your details and our team will follow up with the right troubleshooting guidance,
399.                 account help, or product answers.
400.               </p>
401.             </div>
402.             <ul class="feature-list" aria-label="Support highlights">
403.               <li>
404.                 <span class="bullet" aria-hidden="true"></span>
405.                 <div>
406.                   <strong>Fast routing</strong>
407.                   Requests are triaged so customers reach the right specialist sooner.
408.                 </div>
409.               </li>
410.               <li>
411.                 <span class="bullet" aria-hidden="true"></span>
412.                 <div>
413.                   <strong>Clear follow-up</strong>
414.                   Contact details are collected in a simple format with immediate validation feedback.
415.                 </div>
416.               </li>
417.               <li>
418.                 <span class="bullet" aria-hidden="true"></span>
419.                 <div>
420.                   <strong>Built for every screen</strong>
421.                   The layout stays readable from small mobile widths to larger desktop views.
422.                 </div>
423.               </li>
424.             </ul>
425.           </section>
426.         `;
427.       }
428. 
429.       function App() {
430.         return `
431.           <main id="maincontent" tabindex="-1">
432.             <div class="page-shell">
433.               ${SupportHero()}
434.               ${ContactForm()}
435.             </div>
436.           </main>
437.         `;
438.       }
439. 
440.       function escapeHtml(value) {
441.         return value
442.           .replaceAll("&", "&amp;")
443.           .replaceAll('"', "&quot;")
444.           .replaceAll("<", "&lt;")
445.           .replaceAll(">", "&gt;");
446.       }
447. 
448.       function render() {
449.         document.getElementById("app").innerHTML = App();
450.         const form = document.getElementById("support-form");
451.         const fields = fieldConfig().map((field) => document.getElementById(field.id));
452. 
453.         fields.forEach((input) => {
454.           input.addEventListener("input", handleInput);
455.           input.addEventListener("blur", handleBlur);
456.         });
457. 
458.         form.addEventListener("submit", handleSubmit);
459.         syncUi();
460.       }
461. 
462.       function syncUi() {
463.         fieldConfig().forEach((field) => {
464.           const input = document.getElementById(field.id);
465.           const error = state.errors[field.id];
466.           const describedBy = [field.helperText ? field.id + "-help" : "", error ? field.id + "-error" : ""]
467.             .filter(Boolean)
468.             .join(" ");
469.           const errorNode = document.getElementById(field.id + "-error");
470. 
471.           if (input.value !== state.values[field.id]) {
472.             input.value = state.values[field.id];
473.           }
474. 
475.           if (describedBy) {
476.             input.setAttribute("aria-describedby", describedBy);
477.           } else {
478.             input.removeAttribute("aria-describedby");
479.           }
480. 
481.           if (error) {
482.             input.setAttribute("aria-invalid", "true");
483.             input.setAttribute("aria-errormessage", field.id + "-error");
484.             errorNode.hidden = false;
485.             errorNode.textContent = error;
486.           } else {
487.             input.setAttribute("aria-invalid", "false");
488.             input.removeAttribute("aria-errormessage");
489.             errorNode.hidden = true;
490.             errorNode.textContent = "";
491.           }
492.         });
493. 
494.         document.getElementById("form-status").textContent = state.submitMessage;
495.       }
496. 
497.       function updateState(nextState, options = {}) {
498.         state = {
499.           ...state,
500.           ...nextState,
501.           values: {
502.             ...state.values,
503.             ...(nextState.values || {})
504.           }
505.         };
506. 
507.         syncUi();
508. 
509.         const focusId = options.focusId;
510. 
511.         if (focusId) {
512.           const target = document.getElementById(focusId);
513.           if (target) {
514.             target.focus();
515.           }
516.         }
517.       }
518. 
519.       function handleInput(event) {
520.         const { name, value } = event.target;
521.         const nextValues = { ...state.values, [name]: value };
522.         const nextErrors = { ...state.errors };
523. 
524.         if (nextErrors[name]) {
525.           const refreshedErrors = validate(nextValues);
526.           if (!refreshedErrors[name]) {
527.             delete nextErrors[name];
528.           } else {
529.             nextErrors[name] = refreshedErrors[name];
530.           }
531.         }
532. 
533.         updateState({
534.           values: nextValues,
535.           errors: nextErrors,
536.           submitMessage: ""
537.         });
538.       }
539. 
540.       function handleBlur(event) {
541.         const { name, value } = event.target;
542.         const nextValues = { ...state.values, [name]: value };
543.         const refreshedErrors = validate(nextValues);
544.         const nextErrors = { ...state.errors };
545. 
546.         if (refreshedErrors[name]) {
547.           nextErrors[name] = refreshedErrors[name];
548.         } else {
549.           delete nextErrors[name];
550.         }
551. 
552.         updateState({
553.           values: nextValues,
554.           errors: nextErrors,
555.           submitMessage: ""
556.         });
557.       }
558. 
559.       function handleSubmit(event) {
560.         event.preventDefault();
561.         const nextErrors = validate(state.values);
562.         const firstInvalidId = fieldConfig().find((field) => nextErrors[field.id])?.id;
563. 
564.         if (firstInvalidId) {
565.           updateState({
566.             errors: nextErrors,
567.             submitMessage: ""
568.           }, {
569.             focusId: firstInvalidId
570.           });
571.           return;
572.         }
573. 
574.         updateState({
575.           errors: {},
576.           submitMessage: "Thanks. Your support request is ready to be reviewed."
577.         });
578.       }
