   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>
     <div id="app"></div>
     <script>
       const initialState = {
         values: {
           fullName: "",
           email: "",
           phone: ""
         },
         errors: {},
         submitMessage: ""
       };

       let state = { ...initialState, values: { ...initialState.values } };

       const phonePattern = /^(?:\+?\d{1,2}\s?)?(?:\(\d{3}\)|\d{3})[\s-]?\d{3}[\s-]?\d{4}$/;

       function validate(values) {
         const errors = {};
         const trimmedName = values.fullName.trim();
         const trimmedEmail = values.email.trim();
         const trimmedPhone = values.phone.trim();

         if (!trimmedName) {
           errors.fullName = "Error: Enter your full name.";
         }

         if (!trimmedEmail) {
           errors.email = "Error: Enter your email address.";
         } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedEmail)) {
           errors.email = "Error: Enter a valid email address, like name@example.com.";
         }

         if (trimmedPhone && !phonePattern.test(trimmedPhone)) {
           errors.phone = "Error: Enter a phone number like (555) 123-4567.";
         }

         return errors;
       }

       function fieldConfig() {
         return [
           {
             id: "fullName",
             label: "Full name",
             type: "text",
             required: true,
             autocomplete: "name",
             placeholder: "Taylor Morgan"
           },
           {
             id: "email",
             label: "Email address",
             type: "email",
             required: true,
             autocomplete: "email",
             placeholder: "taylor@example.com"
           },
           {
             id: "phone",
             label: "Phone number",
             type: "tel",
             required: false,
             autocomplete: "tel",
             placeholder: "(555) 123-4567",
             helperText: "Optional. Use a format like (555) 123-4567."
           }
         ];
       }

       function FormField({ id, label, type, required, autocomplete, placeholder, helperText }) {
         const error = state.errors[id];
         const describedBy = [helperText ? id + "-help" : "", error ? id + "-error" : ""]
           .filter(Boolean)
           .join(" ");

         return `
           <div class="form-field">
             <label for="${id}">
               ${label}${required ? '<span class="required-indicator" aria-hidden="true">*</span>' : ' <span aria-hidden="true">(optional)</span>'}
             </label>
             <input
               id="${id}"
               name="${id}"
               type="${type}"
               ${required ? "required" : ""}
               autocomplete="${autocomplete}"
               placeholder="${placeholder}"
               value="${escapeHtml(state.values[id])}"
               ${describedBy ? 'aria-describedby="' + describedBy + '"' : ""}
               ${error ? 'aria-invalid="true" aria-errormessage="' + id + '-error"' : 'aria-invalid="false"'}
             />
             ${helperText ? '<p class="helper-text" id="' + id + '-help">' + helperText + "</p>" : ""}
             <p class="error-message" id="${id}-error"${error ? "" : ' hidden'}>${error || ""}</p>
           </div>
         `;
       }

       function ContactForm() {
         return `
           <section class="card" aria-labelledby="contact-form-title">
             <h2 id="contact-form-title">Send a support request</h2>
             <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required fields</p>
             <form id="support-form" novalidate>
               ${fieldConfig().map(FormField).join("")}
               <div class="button-row">
                 <p class="success-message" aria-live="polite" id="form-status">${state.submitMessage}</p>
                 <button type="submit">Send request</button>
               </div>
             </form>
           </section>
         `;
       }

       function SupportHero() {
         return `
           <section class="hero" aria-labelledby="page-title">
             <div>
               <span class="eyebrow">Support team</span>
               <h1 id="page-title">Talk to product support without the back-and-forth.</h1>
               <p>
                 Share your details and our team will follow up with the right troubleshooting guidance,
                 account help, or product answers.
               </p>
             </div>
             <ul class="feature-list" aria-label="Support highlights">
               <li>
                 <span class="bullet" aria-hidden="true"></span>
                 <div>
                   <strong>Fast routing</strong>
                   Requests are triaged so customers reach the right specialist sooner.
                 </div>
               </li>
               <li>
                 <span class="bullet" aria-hidden="true"></span>
                 <div>
                   <strong>Clear follow-up</strong>
                   Contact details are collected in a simple format with immediate validation feedback.
                 </div>
               </li>
               <li>
                 <span class="bullet" aria-hidden="true"></span>
                 <div>
                   <strong>Built for every screen</strong>
                   The layout stays readable from small mobile widths to larger desktop views.
                 </div>
               </li>
             </ul>
           </section>
         `;
       }

       function App() {
         return `
           <main id="maincontent" tabindex="-1">
             <div class="page-shell">
               ${SupportHero()}
               ${ContactForm()}
             </div>
           </main>
         `;
       }

       function escapeHtml(value) {
         return value
           .replaceAll("&", "&amp;")
           .replaceAll('"', "&quot;")
           .replaceAll("<", "&lt;")
           .replaceAll(">", "&gt;");
       }

       function render() {
         document.getElementById("app").innerHTML = App();
         const form = document.getElementById("support-form");
         const fields = fieldConfig().map((field) => document.getElementById(field.id));

         fields.forEach((input) => {
           input.addEventListener("input", handleInput);
           input.addEventListener("blur", handleBlur);
         });

         form.addEventListener("submit", handleSubmit);
         syncUi();
       }

       function syncUi() {
         fieldConfig().forEach((field) => {
           const input = document.getElementById(field.id);
           const error = state.errors[field.id];
           const describedBy = [field.helperText ? field.id + "-help" : "", error ? field.id + "-error" : ""]
             .filter(Boolean)
             .join(" ");
           const errorNode = document.getElementById(field.id + "-error");

           if (input.value !== state.values[field.id]) {
             input.value = state.values[field.id];
           }

           if (describedBy) {
             input.setAttribute("aria-describedby", describedBy);
           } else {
             input.removeAttribute("aria-describedby");
           }

           if (error) {
             input.setAttribute("aria-invalid", "true");
             input.setAttribute("aria-errormessage", field.id + "-error");
             errorNode.hidden = false;
             errorNode.textContent = error;
           } else {
             input.setAttribute("aria-invalid", "false");
             input.removeAttribute("aria-errormessage");
             errorNode.hidden = true;
             errorNode.textContent = "";
           }
         });

         document.getElementById("form-status").textContent = state.submitMessage;
       }

       function updateState(nextState, options = {}) {
         state = {
           ...state,
           ...nextState,
           values: {
             ...state.values,
             ...(nextState.values || {})
           }
         };

         syncUi();

         const focusId = options.focusId;

         if (focusId) {
           const target = document.getElementById(focusId);
           if (target) {
             target.focus();
           }
         }
       }

       function handleInput(event) {
         const { name, value } = event.target;
         const nextValues = { ...state.values, [name]: value };
         const nextErrors = { ...state.errors };

         if (nextErrors[name]) {
           const refreshedErrors = validate(nextValues);
           if (!refreshedErrors[name]) {
             delete nextErrors[name];
           } else {
             nextErrors[name] = refreshedErrors[name];
           }
         }

         updateState({
           values: nextValues,
           errors: nextErrors,
           submitMessage: ""
         });
       }

       function handleBlur(event) {
         const { name, value } = event.target;
         const nextValues = { ...state.values, [name]: value };
         const refreshedErrors = validate(nextValues);
         const nextErrors = { ...state.errors };

         if (refreshedErrors[name]) {
           nextErrors[name] = refreshedErrors[name];
         } else {
           delete nextErrors[name];
         }

         updateState({
           values: nextValues,
           errors: nextErrors,
           submitMessage: ""
         });
       }

       function handleSubmit(event) {
         event.preventDefault();
         const nextErrors = validate(state.values);
         const firstInvalidId = fieldConfig().find((field) => nextErrors[field.id])?.id;

         if (firstInvalidId) {
           updateState({
             errors: nextErrors,
             submitMessage: ""
           }, {
             focusId: firstInvalidId
           });
           return;
         }

         updateState({
           errors: {},
           submitMessage: "Thanks. Your support request is ready to be reviewed."
         });
       }

       render();
     </script>
   </body>
 </html>

